-- >>> BEGIN 18_notifications_push.sql

-- 14. Push notification fan-out (activity_log -> edge function -> APNs)
-- ============================================================================
-- The in-app Activity feed works without any of this (it reads activity_log via
-- sync). This file wires the *push* channel: an AFTER INSERT trigger on
-- activity_log hands the new event to the `send-push` edge function over pg_net,
-- which resolves recipients (members - actor - muters), looks up their APNs
-- tokens, and sends. See docs/adr/0002-notification-architecture.md.
--
-- Config (function URL + shared secret) lives in private.app_config, seeded
-- out-of-band and NEVER committed. If unset, the trigger no-ops, so the app
-- still works fully without push configured.

create extension if not exists pg_net;

create table if not exists private.app_config (
  key   text primary key,
  value text not null
);

comment on table private.app_config is
  'Out-of-band runtime config (e.g. push webhook url + secret). Not exposed via PostgREST. Seed values manually; never commit them.';

create or replace function private.config(p_key text)
returns text
language sql
security definer
stable
set search_path = private
as $$
  select value from private.app_config where key = p_key;
$$;

-- Unread Activity count for one user: events on their joined trips, not their
-- own, newer than their read cursor, excluding muted trips and anything that
-- predates them joining the trip (a member claimed after months of activity
-- must not start at badge 100). Used by the edge function to stamp aps.badge
-- so the app-icon badge is correct with the app closed.
create or replace function public.unread_activity_count(p_user uuid)
returns integer
language sql
security definer
stable
set search_path = public, private
as $$
  select count(*)::int
  from public.activity_log a
  join public.profiles p on p.id = p_user
  where a.actor_id <> p_user
    and a.timestamp > coalesce(p.activity_last_seen_at, '-infinity'::timestamptz)
    and exists (
      select 1 from public.trip_people tp
      where tp.trip_id = a.trip_id
        and tp.user_id = p_user
        and tp.joined_at is not null
        and tp.removed_at is null
        and a.timestamp >= tp.joined_at
    )
    and not exists (
      select 1 from public.trip_mute_prefs m
      where m.trip_id = a.trip_id and m.user_id = p_user
    );
$$;

comment on function public.unread_activity_count(uuid) is
  'Count of unread Activity events for a user (excludes own actions and muted trips). For the push badge.';

-- One round-trip for the edge function: every device that should receive a push
-- for an activity (members - actor - muters), with that recipient's badge count.
create or replace function public.push_targets_for_activity(p_activity_id uuid)
returns table (user_id uuid, apns_token text, push_device_id uuid, badge integer)
language sql
security definer
stable
set search_path = public, private
as $$
  select pd.user_id, pd.apns_token, pd.id, public.unread_activity_count(pd.user_id)
  from public.activity_log a
  join public.trip_people tp
    on tp.trip_id = a.trip_id
   and tp.user_id is not null
   and tp.user_id <> a.actor_id
   and tp.joined_at is not null
   and tp.removed_at is null
  join public.push_devices pd on pd.user_id = tp.user_id
  where a.id = p_activity_id
    and not exists (
      select 1 from public.trip_mute_prefs m
      where m.trip_id = a.trip_id and m.user_id = tp.user_id
    );
$$;

comment on function public.push_targets_for_activity(uuid) is
  'Recipient devices + badge for an activity event. Called by the send-push edge function (service role).';

create or replace function public.notify_activity_push()
returns trigger
language plpgsql
security definer
set search_path = public, private
as $$
declare
  v_url    text := private.config('push_webhook_url');
  v_secret text := private.config('push_webhook_secret');
begin
  if v_url is null then
    return new;  -- push not configured; in-app Activity still works
  end if;

  perform net.http_post(
    url     := v_url,
    headers := jsonb_build_object(
      'Content-Type',    'application/json',
      'x-webhook-secret', coalesce(v_secret, '')
    ),
    body    := jsonb_build_object(
      'activity_id', new.id,
      'trip_id',     new.trip_id,
      'actor_id',    new.actor_id,
      'action',      new.action,
      'entity_type', new.entity_type,
      'entity_id',   new.entity_id,
      'snapshot',    new.snapshot_json
    )
  );
  return new;
end;
$$;

create trigger trg_activity_notify_push
  after insert on public.activity_log
  for each row execute function public.notify_activity_push();

-- Lock down: these are internal. The edge function calls
-- push_targets_for_activity with the service-role key, which still needs
-- explicit EXECUTE even though it bypasses RLS.
revoke execute on function private.config(text)              from public, anon, authenticated;
revoke execute on function public.notify_activity_push()     from public, anon, authenticated;
revoke execute on function public.unread_activity_count(uuid) from public, anon, authenticated;
revoke execute on function public.push_targets_for_activity(uuid) from public, anon, authenticated;
grant execute on function public.push_targets_for_activity(uuid) to service_role;

-- <<< END 18_notifications_push.sql

-- >>> BEGIN 19_rpc_non_group.sql

-- 19. Client RPC: non-group containers
-- ============================================================================
-- A non-group expense is backed by a hidden trips row (kind='non_group') shared
-- by the exact set of participants. The container is deduplicated by
-- member_signature (the canonical sort of participants' normalised emails), so
-- the same set of people always resolves to one shared container regardless of
-- who creates the expense, and the signature is stable across sign-in/claim
-- (email never changes when a pending row is claimed).

create or replace function public.resolve_or_create_non_group_container(
  p_participants jsonb
)
returns setof public.trip_people
language plpgsql
security definer
set search_path = public, private
as $$
declare
  v_actor     uuid := auth.uid();
  v_email     text := private.current_auth_email();
  v_self_name text;
  v_emails    text[];
  v_signature text;
  v_container uuid;
  v_row       jsonb;
  v_p_email   text;
  v_p_name    text;
begin
  if v_actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if v_email is null or v_email = '' or v_email not like '%@%' then
    raise exception 'A verified email is required to add non-group expenses' using errcode = '22023';
  end if;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then
    raise exception 'participants must be a JSON array' using errcode = '22023';
  end if;

  -- Collect the deduped set of normalised emails (caller + the other participants).
  v_emails := array[v_email];
  for v_row in select * from jsonb_array_elements(p_participants) loop
    v_p_email := private.normalized_email(v_row->>'email');
    if v_p_email is null or v_p_email = '' or v_p_email not like '%@%' or char_length(v_p_email) > 320
       or position('|' in v_p_email) > 0 then
      raise exception 'A valid participant email is required' using errcode = '22023';
    end if;
    if not (v_p_email = any (v_emails)) then
      v_emails := array_append(v_emails, v_p_email);
    end if;
  end loop;

  if array_length(v_emails, 1) < 2 then
    raise exception 'A non-group expense needs at least two people' using errcode = '22023';
  end if;

  -- Canonical participant-set signature: sorted emails joined by '|'.
  select string_agg(e, '|' order by e) into v_signature
  from unnest(v_emails) as e;

  -- Find the existing shared container, or create it.
  select id into v_container
  from public.trips
  where kind = 'non_group' and member_signature = v_signature and deleted_at is null
  limit 1;

  if v_container is null then
    v_container := gen_random_uuid();
    begin
      insert into public.trips (id, name, kind, member_signature, created_by)
      values (v_container, '', 'non_group', v_signature, v_actor);
    exception when unique_violation then
      -- Another transaction created the same participant-set container concurrently.
      select id into v_container
      from public.trips
      where kind = 'non_group' and member_signature = v_signature and deleted_at is null
      limit 1;
    end;
  end if;

  -- Caller's display name (ensure their profile exists).
  insert into public.profiles (id, display_name)
  values (v_actor, left(split_part(v_email, '@', 1), 60))
  on conflict (id) do nothing;

  select left(coalesce(nullif(trim(display_name), ''), split_part(v_email, '@', 1)), 60)
  into v_self_name
  from public.profiles where id = v_actor;

  -- The caller must be a joined member so create_expense_with_payments_and_splits
  -- (which requires is_profile_trip_member) accepts their write.
  insert into public.trip_people (id, trip_id, user_id, email, display_name, invited_by, joined_at)
  values (gen_random_uuid(), v_container, v_actor, v_email, v_self_name, v_actor, clock_timestamp())
  on conflict on constraint trip_people_email_unique do update
    set user_id   = v_actor,
        joined_at = coalesce(public.trip_people.joined_at, clock_timestamp())
    -- A claimed row never transfers to another account.
    where public.trip_people.user_id is null
       or public.trip_people.user_id = v_actor;

  if not exists (
    select 1 from public.trip_people
    where trip_id = v_container and email = v_email and user_id = v_actor
  ) then
    raise exception 'This email is already claimed by another account in this group'
      using errcode = '42501';
  end if;

  -- Ensure each other participant stays pending until that email's owner signs
  -- in and claims it. Do not query auth.users here; that would let callers
  -- probe whether an arbitrary email already has a Tab account.
  for v_row in select * from jsonb_array_elements(p_participants) loop
    v_p_email := private.normalized_email(v_row->>'email');
    if v_p_email = v_email then
      continue;
    end if;

    v_p_name := left(coalesce(nullif(trim(v_row->>'display_name'), ''), split_part(v_p_email, '@', 1)), 60);

    insert into public.trip_people (id, trip_id, user_id, email, display_name, invited_by, joined_at)
    values (
      gen_random_uuid(), v_container, null, v_p_email, v_p_name, v_actor, null
    )
    on conflict on constraint trip_people_email_unique do update
      set display_name = excluded.display_name;
  end loop;

  return query
  select tp.* from public.trip_people tp where tp.trip_id = v_container;
end;
$$;

comment on function public.resolve_or_create_non_group_container(jsonb) is
  'Finds or creates the hidden non-group container for the canonical set of participant emails (caller + p_participants [{email, display_name}]), ensuring a trip_people row for each without probing auth.users for other participants. Idempotent by member_signature. Returns the container''s trip_people rows; the caller derives container_id from trip_id.';

-- Privileges are granted here rather than in 17_privileges.sql because that
-- file sorts before this one in the baseline build — a fresh database would
-- fail on a revoke against a function that does not exist yet.
revoke execute on function public.resolve_or_create_non_group_container(jsonb) from public, anon;
grant  execute on function public.resolve_or_create_non_group_container(jsonb) to authenticated;

-- <<< END 19_rpc_non_group.sql

-- >>> BEGIN 20_account_deletion.sql

-- 20. Account deletion (App Store 5.1.1(v))
-- ============================================================================
-- Called by the delete-account edge function with the service role, before it
-- deletes the auth.users row via the admin API. Hard-deletes everything only
-- the user could see, anonymizes their identity in shared trips, and returns
-- receipt storage paths for the edge function to remove (storage objects
-- cannot be deleted from SQL).

create or replace function public.delete_account_data(p_user uuid)
returns table (receipt_path text)
language plpgsql
security definer
set search_path = public, private
as $$
declare
  v_sole_trips uuid[];
begin
  if p_user is null then
    raise exception 'p_user is required';
  end if;

  -- Trips where the user is a claimed member and nobody else ever claimed one:
  -- invisible to everyone else, so they go entirely (regardless of soft-delete
  -- state). Pending email-only people cannot see a trip.
  select coalesce(array_agg(t.id), '{}') into v_sole_trips
  from public.trips t
  where exists (
          select 1 from public.trip_people tp
          where tp.trip_id = t.id and tp.user_id = p_user
        )
    and not exists (
          select 1 from public.trip_people tp
          where tp.trip_id = t.id and tp.user_id is not null and tp.user_id <> p_user
        );

  -- Surface receipt paths before the expense rows go.
  return query
    select e.receipt_storage_path
    from public.expenses e
    where e.trip_id = any (v_sole_trips)
      and e.receipt_storage_path is not null;

  -- Order matters: payments/splits cascade from expenses, settlements
  -- restrict-reference trip_people, and the member-left activity trigger
  -- inserts a row referencing the trip — so people go before trips.
  delete from public.expenses    where trip_id = any (v_sole_trips);
  delete from public.settlements where trip_id = any (v_sole_trips);
  delete from public.trip_people where trip_id = any (v_sole_trips);
  delete from public.trips       where id      = any (v_sole_trips);

  -- Shared trips keep their ledger rows (they are the group's data). The
  -- user's claimed identity rows lose the personal email; the trip-scoped
  -- display name stays as the ledger label.
  update public.trip_people tp
  set email = 'deleted-' || tp.id || '@account-deleted.invalid'
  where tp.user_id = p_user;

  delete from public.push_devices    where user_id = p_user;
  delete from public.trip_mute_prefs where user_id = p_user;

  -- Ghost the profile: shared-trip ledger rows restrict-reference it, so it
  -- stays — anonymized and no longer tied to any auth identity.
  update public.profiles
  set display_name = 'Deleted user',
      avatar_url = null,
      activity_last_seen_at = null,
      deleted_at = now()
  where id = p_user;
end;
$$;

comment on function public.delete_account_data(uuid) is
  'Account-deletion purge: hard-deletes sole-member trips, scrubs identity from shared trips, ghosts the profile. Service-role only; the edge function deletes the auth user afterwards.';

revoke execute on function public.delete_account_data(uuid) from public, anon, authenticated;
grant  execute on function public.delete_account_data(uuid) to service_role;


-- ============================================================================

-- <<< END 20_account_deletion.sql

-- >>> BEGIN 21_trip_invites.sql

-- 21. Trip invite links
-- ============================================================================
-- A trip has at most one active secret invite link. Anyone who opens the link
-- in the app and signs in becomes a joined trip member — the link is an
-- authenticated door into the trip, with no claim/merge step. Email pre-add +
-- auto-claim (15_rpc_trip_people.sql) is unchanged and complements this.
--
-- The token is the whole secret: possession grants membership. Members can
-- revoke the active link at any time; the next share mints a fresh token.
-- Invites are not client-synced — the app fetches them on demand via RPC, and
-- all writes go through SECURITY DEFINER RPCs below.

create table public.trip_invites (
  id         uuid primary key default gen_random_uuid(),
  trip_id    uuid not null references public.trips(id) on delete cascade,
  token      text not null check (token ~ '^[0-9a-f]{32}$'),
  created_by uuid not null references public.profiles(id) on delete restrict,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  write_id   uuid not null default gen_random_uuid(),
  constraint trip_invites_token_unique unique (token)
);

comment on table public.trip_invites is
  'Per-trip secret join links. At most one active (revoked_at is null) invite per trip; the 128-bit hex token is the whole secret. Never client-synced; accessed only through RPCs.';

-- One active invite per trip; revoked invites are kept for audit.
create unique index trip_invites_active_uniq on public.trip_invites(trip_id)
  where revoked_at is null;
create index trip_invites_trip_id_idx on public.trip_invites(trip_id);
create index trip_invites_created_by_idx on public.trip_invites(created_by);

create trigger trg_trip_invites_sync_fields
  before insert or update on public.trip_invites
  for each row execute function public.set_sync_fields();

alter table public.trip_invites enable row level security;

-- Members may read their trip's invites (so any member can re-share or see
-- revocation state). All writes go through the RPCs below.
create policy trip_invites_select_member on public.trip_invites
  for select to authenticated using (private.is_trip_member(trip_id));

create or replace function public.get_or_create_trip_invite(
  p_trip_id uuid
)
returns public.trip_invites
language plpgsql
security definer
set search_path = public, private
as $$
declare
  v_actor uuid := auth.uid();
  v_invite public.trip_invites;
begin
  if v_actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if exists (select 1 from public.trips t where t.id = p_trip_id and t.kind <> 'trip') then
    raise exception 'Group-trip RPC cannot target non-group containers' using errcode = '42501';
  end if;

  if not exists (select 1 from public.trips t where t.id = p_trip_id and t.kind = 'trip' and t.deleted_at is null) then
    raise exception 'Trip not found or deleted' using errcode = 'P0002';
  end if;

  if not private.is_profile_trip_member(p_trip_id, v_actor) then
    raise exception 'Only trip members can share invite links' using errcode = '42501';
  end if;

  select * into v_invite
  from public.trip_invites
  where trip_id = p_trip_id and revoked_at is null;

  if found then
    return v_invite;
  end if;

  insert into public.trip_invites (trip_id, token, created_by)
  values (p_trip_id, encode(extensions.gen_random_bytes(16), 'hex'), v_actor)
  on conflict (trip_id) where revoked_at is null do nothing
  returning * into v_invite;

  -- Concurrent get_or_create: someone else won the insert race.
  if v_invite.id is null then
    select * into v_invite
    from public.trip_invites
    where trip_id = p_trip_id and revoked_at is null;
  end if;

  return v_invite;
end;
$$;

comment on function public.get_or_create_trip_invite(uuid) is
  'Returns the trip''s active invite link, minting one if none exists. Member-only; called when a member taps share.';

create or replace function public.revoke_trip_invite(
  p_trip_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, private
as $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if not private.is_profile_trip_member(p_trip_id, v_actor) then
    raise exception 'Only trip members can revoke invite links' using errcode = '42501';
  end if;

  update public.trip_invites
  set revoked_at = clock_timestamp()
  where trip_id = p_trip_id and revoked_at is null;
end;
$$;

comment on function public.revoke_trip_invite(uuid) is
  'Turns off the trip''s active invite link. Idempotent; the next get_or_create_trip_invite mints a fresh token.';

create or replace function public.join_trip_with_invite(
  p_token text,
  p_person_id uuid default null
)
returns table (
  trip_id uuid,
  person_id uuid,
  trip_name text
)
language plpgsql
security definer
set search_path = public, private
as $$
declare
  v_actor uuid := auth.uid();
  v_email text := private.current_auth_email();
  v_token text := lower(trim(p_token));
  v_invite public.trip_invites;
  v_display_name text;
begin
  if v_actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if v_email is null or v_email = '' or v_email not like '%@%' then
    raise exception 'A verified email is required to join trips' using errcode = '22023';
  end if;

  select ti.* into v_invite
  from public.trip_invites ti
  join public.trips t on t.id = ti.trip_id
  where ti.token = v_token
    and ti.revoked_at is null
    and t.kind = 'trip'
    and t.deleted_at is null;

  if not found then
    raise exception 'This invite link is invalid or was turned off' using errcode = 'P0002';
  end if;

  select t.name into trip_name from public.trips t where t.id = v_invite.trip_id;

  select p.display_name into v_display_name
  from public.profiles p
  where p.id = v_actor;

  -- The deep link can be the first RPC after sign-in, before the app has
  -- ensured a profile row exists.
  insert into public.profiles (id, display_name)
  values (v_actor, left(coalesce(nullif(trim(v_display_name), ''), split_part(v_email, '@', 1)), 60))
  on conflict (id) do nothing;

  v_display_name := left(coalesce(nullif(trim(v_display_name), ''), split_part(v_email, '@', 1)), 60);

  -- Already claimed a person row in this trip (any email): opening the link
  -- is a rejoin — holding the secret link is equivalent to being re-added.
  update public.trip_people tp
  set removed_at = null
  where tp.trip_id = v_invite.trip_id
    and tp.user_id = v_actor
  returning tp.id into person_id;

  if person_id is not null then
    trip_id := v_invite.trip_id;
    return next;
    return;
  end if;

  -- Otherwise claim the pending row for this email (restoring it if removed —
  -- same rationale as above), or insert a fresh member. A pending row claimed
  -- by a different account never transfers.
  insert into public.trip_people (
    id, trip_id, user_id, email, display_name, invited_by, joined_at
  )
  values (
    coalesce(p_person_id, gen_random_uuid()),
    v_invite.trip_id,
    v_actor,
    v_email,
    v_display_name,
    v_invite.created_by,
    clock_timestamp()
  )
  on conflict on constraint trip_people_email_unique do update
    set user_id = v_actor,
        display_name = excluded.display_name,
        joined_at = coalesce(public.trip_people.joined_at, clock_timestamp()),
        removed_at = null
    where public.trip_people.user_id is null
  returning public.trip_people.id into person_id;

  if person_id is null then
    raise exception 'Person row for % is already claimed by another account', v_email
      using errcode = '42501';
  end if;

  trip_id := v_invite.trip_id;
  return next;
end;
$$;

comment on function public.join_trip_with_invite(text, uuid) is
  'Joins the current user to the trip behind an active invite token. Idempotent: existing members (including removed ones) are restored, a pending row matching the auth email is claimed, otherwise a new member row is created. Returns the trip so the app can sync and navigate.';

revoke execute on function public.get_or_create_trip_invite(uuid) from public, anon;
grant  execute on function public.get_or_create_trip_invite(uuid) to authenticated;
revoke execute on function public.revoke_trip_invite(uuid) from public, anon;
grant  execute on function public.revoke_trip_invite(uuid) to authenticated;
revoke execute on function public.join_trip_with_invite(text, uuid) from public, anon;
grant  execute on function public.join_trip_with_invite(text, uuid) to authenticated;


-- ============================================================================

-- <<< END 21_trip_invites.sql
